Bindings.Binding:
if MBB_Options and MBB_MinimapButtonFrame and not InCombatLockdown() then
    MBB_OnClick("LeftButton");
    if MBB_IsShown == 1 and not MBB_MinimapButtonFrame:IsMouseOver() then
        MBB_ShowTimeout = 0;
    end
end

if MBB_OpenOptions and not InCombatLockdown() then
    MBB_OpenOptions();
end
